create type public.app_role as enum ('admin','editor');
create table public.user_roles (id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id) on delete cascade not null, role app_role not null, unique(user_id,role));
grant select on public.user_roles to authenticated; grant all on public.user_roles to service_role;
alter table public.user_roles enable row level security;
create or replace function public.has_role(_user_id uuid,_role app_role) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.user_roles where user_id=_user_id and role=_role) $$;
create policy "own roles" on public.user_roles for select to authenticated using (user_id=auth.uid() or public.has_role(auth.uid(),'admin'));
-- first user becomes admin
create or replace function public.handle_first_admin() returns trigger language plpgsql security definer set search_path=public as $$ begin if not exists(select 1 from public.user_roles where role='admin') then insert into public.user_roles(user_id,role) values(new.id,'admin'); end if; return new; end $$;
create trigger on_auth_user_first_admin after insert on auth.users for each row execute function public.handle_first_admin();

create table public.practice_areas (id uuid primary key default gen_random_uuid(), slug text unique not null, title text not null, icon text not null default 'Scale', summary text not null default '', intro text not null default '', matters text[] not null default '{}', situations text[] not null default '{}', approach text not null default '', sort_order int not null default 0, published boolean not null default true, created_at timestamptz not null default now());
create table public.lawyers (id uuid primary key default gen_random_uuid(), slug text unique not null, name text not null, title text not null default '', photo_url text, qualifications text[] not null default '{}', practice_areas text[] not null default '{}', short_bio text not null default '', bio text not null default '', experience text not null default '', languages text[] not null default '{}', email text, sort_order int not null default 0, published boolean not null default true, created_at timestamptz not null default now());
create table public.articles (id uuid primary key default gen_random_uuid(), slug text unique not null, title text not null, category text not null default 'Legal Updates', excerpt text not null default '', body text not null default '', image_url text, author text not null default 'Lawtribe Legal Consult', featured boolean not null default false, published boolean not null default false, published_at timestamptz not null default now(), created_at timestamptz not null default now());
create table public.enquiries (id uuid primary key default gen_random_uuid(), full_name text not null, email text not null, phone text, subject text not null, area text, message text not null, status text not null default 'new', notes text not null default '', created_at timestamptz not null default now());
create table public.consultations (id uuid primary key default gen_random_uuid(), full_name text not null, email text not null, phone text not null, method text not null, preferred_date date not null, preferred_time text not null, area text, description text not null, status text not null default 'pending', notes text not null default '', created_at timestamptz not null default now());

grant select on public.practice_areas, public.lawyers, public.articles to anon;
grant select,insert,update,delete on public.practice_areas, public.lawyers, public.articles, public.enquiries, public.consultations to authenticated;
grant all on public.practice_areas, public.lawyers, public.articles, public.enquiries, public.consultations to service_role;
alter table public.practice_areas enable row level security; alter table public.lawyers enable row level security; alter table public.articles enable row level security; alter table public.enquiries enable row level security; alter table public.consultations enable row level security;
create policy "public read" on public.practice_areas for select using (published or public.has_role(auth.uid(),'admin'));
create policy "public read" on public.lawyers for select using (published or public.has_role(auth.uid(),'admin'));
create policy "public read" on public.articles for select using (published or public.has_role(auth.uid(),'admin'));
create policy "admin write" on public.practice_areas for all to authenticated using (public.has_role(auth.uid(),'admin')) with check (public.has_role(auth.uid(),'admin'));
create policy "admin write" on public.lawyers for all to authenticated using (public.has_role(auth.uid(),'admin')) with check (public.has_role(auth.uid(),'admin'));
create policy "admin write" on public.articles for all to authenticated using (public.has_role(auth.uid(),'admin')) with check (public.has_role(auth.uid(),'admin'));
create policy "admin all" on public.enquiries for all to authenticated using (public.has_role(auth.uid(),'admin')) with check (public.has_role(auth.uid(),'admin'));
create policy "admin all" on public.consultations for all to authenticated using (public.has_role(auth.uid(),'admin')) with check (public.has_role(auth.uid(),'admin'));

insert into public.practice_areas (slug,title,icon,summary,intro,matters,situations,approach,sort_order) values
('corporate-commercial','Corporate and Commercial Law','Building2','Counsel on company formation, governance, transactions and commercial agreements.','We advise businesses on the full lifecycle of corporate activity, from incorporation under the Companies Act, 2019 (Act 992) to complex commercial transactions.',array['Company incorporation and registration','Corporate governance and board advisory','Shareholder and joint venture agreements','Mergers, acquisitions and restructuring','Commercial contracts'],array['Starting or restructuring a business','Entering a partnership or joint venture','Negotiating a significant commercial contract'],'We take time to understand your commercial objectives, then structure practical, compliant solutions that protect your interests.',1),
('litigation-disputes','Litigation and Dispute Resolution','Gavel','Representation in civil and commercial disputes before the courts.','We represent clients in civil and commercial disputes, pursuing resolution through negotiation, mediation, arbitration or the courts as each matter requires.',array['Civil and commercial litigation','Contract disputes','Debt recovery','Injunctions and urgent applications','Appeals'],array['A counterparty has breached a contract','You have been served with a writ','You need to recover an outstanding debt'],'We assess the merits early and candidly, recommending the most efficient route to resolution.',2),
('property-real-estate','Property and Real Estate Law','Landmark','Guidance on land acquisition, conveyancing, leases and property disputes.','We support individuals, families and investors with property transactions and land matters, with attention to the Land Act, 2020 (Act 1036).',array['Land searches and due diligence','Conveyancing and title registration','Leases and tenancy agreements','Property development','Land and boundary disputes'],array['Purchasing land or a home','Leasing commercial premises','Resolving a dispute over title'],'We conduct careful due diligence so that your investment rests on secure legal foundations.',3),
('family-matrimonial','Family and Matrimonial Law','Users','Sensitive, discreet advice on marriage, divorce, custody and succession.','We handle family matters with discretion and care, helping clients through difficult personal circumstances.',array['Divorce and separation','Child custody and maintenance','Property settlement','Wills and succession'],array['Considering separation or divorce','Arranging care for children','Planning your estate'],'We combine empathy with firm, clear advice focused on lasting outcomes.',4),
('employment-labour','Employment and Labour Law','Briefcase','Advice for employers and employees on workplace rights and obligations.','We advise on employment relationships with reference to the Labour Act, 2003 (Act 651).',array['Employment contracts and policies','Termination and redundancy','Workplace disputes','Regulatory compliance'],array['Drafting staff contracts','Facing or managing a dismissal','Responding to a workplace grievance'],'We help clients prevent disputes through sound documentation, and resolve them firmly when they arise.',5),
('alternative-dispute-resolution','Alternative Dispute Resolution','Handshake','Mediation, arbitration and negotiated settlement of disputes.','We guide clients through confidential, efficient dispute resolution under the Alternative Dispute Resolution Act, 2010 (Act 798).',array['Mediation','Arbitration','Negotiated settlements'],array['Preserving a commercial relationship during a dispute','A contract requires arbitration'],'We seek outcomes that save time and cost while protecting your position.',6);

